export const COPY: Record<Lang, Copy> = { ko, en };

export const money = (lang: Lang, value: number) =>
  lang === "en" ? `KRW ${new Intl.NumberFormat("en-US").format(value)}` : `${new Intl.NumberFormat("ko-KR").format(value)}원`;
